// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AdminGetAds Ads in free stores, their settings and banners
	// (GET /admin/v1/ads)
	AdminGetAds(ctx context.Context, request AdminGetAdsRequestObject) (AdminGetAdsResponseObject, error)
	// AdminCreateAdBanner Add a banner, active
	// (POST /admin/v1/ads/banners)
	AdminCreateAdBanner(ctx context.Context, request AdminCreateAdBannerRequestObject) (AdminCreateAdBannerResponseObject, error)
	// AdminSetAdBannerActive Show or stop a banner
	// (PUT /admin/v1/ads/banners/{banner_id}/active)
	AdminSetAdBannerActive(ctx context.Context, request AdminSetAdBannerActiveRequestObject) (AdminSetAdBannerActiveResponseObject, error)
	// AdminSaveAdSettings Save Google AdSense's settings
	// (PUT /admin/v1/ads/settings)
	AdminSaveAdSettings(ctx context.Context, request AdminSaveAdSettingsRequestObject) (AdminSaveAdSettingsResponseObject, error)
	// AdminCreateAdUpload Upload a banner's image
	// (POST /admin/v1/ads/uploads)
	AdminCreateAdUpload(ctx context.Context, request AdminCreateAdUploadRequestObject) (AdminCreateAdUploadResponseObject, error)
	// AdminListAgencies Every agency, newest first
	// (GET /admin/v1/agencies)
	AdminListAgencies(ctx context.Context, request AdminListAgenciesRequestObject) (AdminListAgenciesResponseObject, error)
	// AdminCreateAgency Open an agency account
	// (POST /admin/v1/agencies)
	AdminCreateAgency(ctx context.Context, request AdminCreateAgencyRequestObject) (AdminCreateAgencyResponseObject, error)
	// AdminGetAgency An agency and its stores
	// (GET /admin/v1/agencies/{agency_id})
	AdminGetAgency(ctx context.Context, request AdminGetAgencyRequestObject) (AdminGetAgencyResponseObject, error)
	// AdminAddAgencyStore Move a store into an agency
	// (POST /admin/v1/agencies/{agency_id}/stores/{store_id})
	AdminAddAgencyStore(ctx context.Context, request AdminAddAgencyStoreRequestObject) (AdminAddAgencyStoreResponseObject, error)
	// AdminRemoveAgencyStore Take a store out of an agency, onto the free plan
	// (POST /admin/v1/agencies/{agency_id}/stores/{store_id}/remove)
	AdminRemoveAgencyStore(ctx context.Context, request AdminRemoveAgencyStoreRequestObject) (AdminRemoveAgencyStoreResponseObject, error)
	// AdminAuditLog Every admin action, newest first
	// (GET /admin/v1/audit-log)
	AdminAuditLog(ctx context.Context, request AdminAuditLogRequestObject) (AdminAuditLogResponseObject, error)
	// AdminLogin Admin sign-in (password and TOTP code together)
	// (POST /admin/v1/auth/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// AdminLogout End the admin session
	// (POST /admin/v1/auth/logout)
	AdminLogout(ctx context.Context, request AdminLogoutRequestObject) (AdminLogoutResponseObject, error)
	// AdminListDuplicatePayments Payments of invoices already paid, to refund
	// (GET /admin/v1/billing/duplicates)
	AdminListDuplicatePayments(ctx context.Context, request AdminListDuplicatePaymentsRequestObject) (AdminListDuplicatePaymentsResponseObject, error)
	// AdminMarkDuplicateRefunded Record a duplicate payment refunded on the gateway
	// (POST /admin/v1/billing/duplicates/{payment_id}/refunded)
	AdminMarkDuplicateRefunded(ctx context.Context, request AdminMarkDuplicateRefundedRequestObject) (AdminMarkDuplicateRefundedResponseObject, error)
	// AdminListFeatures The features catalog plans grant from
	// (GET /admin/v1/features)
	AdminListFeatures(ctx context.Context, request AdminListFeaturesRequestObject) (AdminListFeaturesResponseObject, error)
	// AdminSaveFeature Add a feature, or rename and reorder one
	// (PUT /admin/v1/features/{key})
	AdminSaveFeature(ctx context.Context, request AdminSaveFeatureRequestObject) (AdminSaveFeatureResponseObject, error)
	// AdminHealth The platform at a glance
	// (GET /admin/v1/health)
	AdminHealth(ctx context.Context, request AdminHealthRequestObject) (AdminHealthResponseObject, error)
	// AdminMe The signed-in admin
	// (GET /admin/v1/me)
	AdminMe(ctx context.Context, request AdminMeRequestObject) (AdminMeResponseObject, error)
	// AdminListPlans Every version of every plan
	// (GET /admin/v1/plans)
	AdminListPlans(ctx context.Context, request AdminListPlansRequestObject) (AdminListPlansResponseObject, error)
	// AdminPublishPlan Put a plan version on sale
	// (POST /admin/v1/plans)
	AdminPublishPlan(ctx context.Context, request AdminPublishPlanRequestObject) (AdminPublishPlanResponseObject, error)
	// AdminRetirePlan Take a plan off sale
	// (POST /admin/v1/plans/{code}/retire)
	AdminRetirePlan(ctx context.Context, request AdminRetirePlanRequestObject) (AdminRetirePlanResponseObject, error)
	// AdminListStores Search every store
	// (GET /admin/v1/stores)
	AdminListStores(ctx context.Context, request AdminListStoresRequestObject) (AdminListStoresResponseObject, error)
	// AdminGetStore One store with its domains
	// (GET /admin/v1/stores/{store_id})
	AdminGetStore(ctx context.Context, request AdminGetStoreRequestObject) (AdminGetStoreResponseObject, error)
	// AdminGetStoreBilling A store's plan, status, card and open invoices
	// (GET /admin/v1/stores/{store_id}/billing)
	AdminGetStoreBilling(ctx context.Context, request AdminGetStoreBillingRequestObject) (AdminGetStoreBillingResponseObject, error)
	// AdminGetStoreEntitlements What a store's plan grants, its overrides, and the result
	// (GET /admin/v1/stores/{store_id}/entitlements)
	AdminGetStoreEntitlements(ctx context.Context, request AdminGetStoreEntitlementsRequestObject) (AdminGetStoreEntitlementsResponseObject, error)
	// AdminSetStoreOverride Grant one store a feature instead of its plan's grant
	// (PUT /admin/v1/stores/{store_id}/entitlements/{feature})
	AdminSetStoreOverride(ctx context.Context, request AdminSetStoreOverrideRequestObject) (AdminSetStoreOverrideResponseObject, error)
	// AdminClearStoreOverride Give a store its plan's grant of a feature again
	// (POST /admin/v1/stores/{store_id}/entitlements/{feature}/clear)
	AdminClearStoreOverride(ctx context.Context, request AdminClearStoreOverrideRequestObject) (AdminClearStoreOverrideResponseObject, error)
	// AdminImpersonateStore Open a time-limited support session as the store's owner
	// (POST /admin/v1/stores/{store_id}/impersonate)
	AdminImpersonateStore(ctx context.Context, request AdminImpersonateStoreRequestObject) (AdminImpersonateStoreResponseObject, error)
	// AdminSettleInvoice Record an invoice as paid outside the card (a confirmed transfer)
	// (POST /admin/v1/stores/{store_id}/invoices/{invoice_id}/settle)
	AdminSettleInvoice(ctx context.Context, request AdminSettleInvoiceRequestObject) (AdminSettleInvoiceResponseObject, error)
	// AdminReactivateStore Reactivate a suspended store
	// (POST /admin/v1/stores/{store_id}/reactivate)
	AdminReactivateStore(ctx context.Context, request AdminReactivateStoreRequestObject) (AdminReactivateStoreResponseObject, error)
	// AdminSuspendStore Suspend an active store (storefront answers 503)
	// (POST /admin/v1/stores/{store_id}/suspend)
	AdminSuspendStore(ctx context.Context, request AdminSuspendStoreRequestObject) (AdminSuspendStoreResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

